input.new_string:
// Handle AI-powered free conversation
setLoading(true);

// First, try to process numeric input the same way as in guided mode
let displayText = textToSend;

// If input is a number and we're in time selection or date selection mode
const numericInput = textToSend.trim().match(/^(\d+)$/);
if (numericInput) {
  // Display available time slots if applicable
  if (ctx.step === 5 && availableTimes.length > 0) {
    const optionIndex = parseInt(numericInput[1], 10) - 1;
    const availableTimeSlots = availableTimes.map(time => time.formatted);
    if (optionIndex >= 0 && optionIndex < availableTimeSlots.length) {
      displayText = availableTimeSlots[optionIndex];
    }
  }

  // Display available dates if applicable
  if (ctx.step === 4 && availableDates.length > 0) {
    const optionIndex = parseInt(numericInput[1], 10) - 1;
    const availableDateOptions = availableDates.map(date => date.display);
    if (optionIndex >= 0 && optionIndex < availableDateOptions.length) {
      displayText = availableDateOptions[optionIndex];
    }
  }
}

callChatApi([
  ...messages,
  { role: 'user', content: displayText }
])

