  1	/* ────────────────────────────────────────────────────────────────
  2	   api.js – SAM back-end helper with Cognito auth & mock fallback
  3	   ----------------------------------------------------------------
  4	   – GET /config?shop_id=…         (Cognito-protected)
  5	   – PUT /config                   (Cognito-protected)
  6	   – GET /appointments?shop_id=…
  7	   – POST /appointments/book
  8	   – GET /workers
  9	   ---------------------------------------------------------------- */
 10	
 11	   import {
 12	    mockAppointments,
 13	    mockWorkers,
 14	    generateEmptyMockData,
 15	  } from './mockData';
 16	  
 17	  /* ── env & helpers ────────────────────────────────────────────── */
 18	  const API_BASE = process.env.REACT_APP_BACKEND_URL;
 19	  
 20	  const shopId = () => sessionStorage.getItem('shopId') || 'demo-shop';
 21	  
 22	  const isMockMode = () =>
 23	    !API_BASE ||
 24	    (API_BASE.startsWith('http://localhost') && !navigator.onLine);
 25	  
 26	  const getDatabaseConfig = () => {
 27	    try {
 28	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
 29	      const storageKey = `appConfig_${shop}`;
 30	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
 31	      return cfg.database || {};
 32	    } catch {
 33	      return {};
 34	    }
 35	  };
 36	  
 37	  /** Build headers with the JWT we stored after Hosted-UI login */
 38	  async function authHeader() {
 39	    const token = sessionStorage.getItem('idToken');
 40	    return {
 41	      Authorization: `Bearer ${token}`,
 42	      'Content-Type': 'application/json',
 43	    };
 44	  }
 45	  
 46	  /* ────────────────────────────────────────────────────────────────
 47	     1)  CONFIG  – GET & PUT (Cognito protected)
 48	     ---------------------------------------------------------------- */
 49	  export async function fetchConfig(shop = shopId()) {
 50	    if (isMockMode()) return {};
 51	    try {
 52	      const headers = await authHeader();
 53	      
 54	      // If token is missing, return empty config to prevent 401 errors
 55	      if (!headers.Authorization || headers.Authorization === 'Bearer undefined' || headers.Authorization === 'Bearer null') {
 56	        console.warn('Missing authentication token, returning empty config');
 57	        return {};
 58	      }
 59	      
 60	      const r = await fetch(`${API_BASE}/config?shop_id=${shop}`, { headers });
 61	      if (!r.ok) {
 62	        console.warn(`API responded with status ${r.status}: ${r.statusText}`);
 63	        return {}; // Return empty config instead of throwing
 64	      }
 65	      return r.json(); // {} if nothing saved yet
 66	    } catch (error) {
 67	      console.error('Error fetching config:', error);
 68	      return {}; // Return empty config instead of throwing
 69	    }
 70	  }
 71	  
 72	  export async function saveConfig(cfg, shop = shopId()) {
 73	    if (isMockMode()) return;
 74	    try {
 75	      const headers = await authHeader();
 76	      
 77	      // Ensure shop_id is correctly set to the current user's shop ID
 78	      // The backend will use the shop_id from JWT claims but we set it explicitly for clarity
 79	      const payload = { ...cfg, shop_id: shop }; // partition key for DynamoDB
 80	      
 81	      const r = await fetch(`${API_BASE}/config`, {
 82	        method: 'PUT',
 83	        headers,
 84	        body: JSON.stringify(payload),
 85	      });
 86	      if (!r.ok) throw new Error(await r.text());
 87	      return r.json();
 88	    } catch (error) {
 89	      console.error('Error saving config:', error);
 90	      throw error;
 91	    }
 92	  }
 93	  
 94	  /* ────────────────────────────────────────────────────────────────
 95	     2)  APPOINTMENTS – GET
 96	     ---------------------------------------------------------------- */
 97	  export async function fetchAppointments(dateISO) {
 98	    /* Offline / mock */
 99	    if (isMockMode()) {
100	      return mockAppointments.filter((a) => !dateISO || a.date === dateISO);
101	    }
102	  
103	    try {
104	      const headers = await authHeader();
105	      
106	      // If token is missing, return empty appointments to prevent 401 errors
107	      if (!headers.Authorization || headers.Authorization === 'Bearer undefined' || headers.Authorization === 'Bearer null') {
108	        console.warn('Missing authentication token, returning empty appointments');
109	        return [];
110	      }
111	      
112	      const base = `${API_BASE}/appointments?shop_id=${shopId()}`;
113	      const url = dateISO ? `${base}&date=${dateISO}` : base;
114	    
115	      const r = await fetch(url, { headers });
116	      if (!r.ok) {
117	        console.warn(`API responded with status ${r.status}: ${r.statusText}`);
118	        return []; // Return empty array instead of throwing
119	      }
120	      
121	      const data = await r.json();
122	      return data.appointments || [];
123	    } catch (error) {
124	      console.error('Error fetching appointments:', error);
125	      return []; // Return empty array instead of throwing
126	    }
127	  }
128	  
129	  /* ────────────────────────────────────────────────────────────────
130	     3)  WORKERS – GET
131	     ---------------------------------------------------------------- */
132	  export async function fetchWorkers() {
133	    const role = sessionStorage.getItem('userRole');
134	  
135	    /* 1) Individual tenant = single “worker” (the shop owner) */
136	    if (role === 'individual') {
137	      const ownerId   = sessionStorage.getItem('shopId');
138	      const ownerName = sessionStorage.getItem('workerName') || ownerId;
139	      return [{ worker_id: ownerId, name: ownerName }];
140	    }
141	  
142	    /* 2) Mock / offline */
143	    if (isMockMode()) {
144	      const empty = getDatabaseConfig().useEmptyData === true;
145	      return empty ? generateEmptyMockData().workers : mockWorkers;
146	    }
147	  
148	    /* 3) Live call */
149	    const headers = await authHeader();
150	    const res     = await fetch(`${API_BASE}/workers`, { headers });
151	    if (!res.ok) throw new Error(`Failed to fetch workers: ${res.statusText}`);
152	  
153	    const { workers = [] } = await res.json();
154	    return workers.map((w) => ({
155	      worker_id: w.worker_id,
156	      name: w.name || w.worker_id,
157	      ...w,
158	    }));
159	  }
160	  
161	  /* ────────────────────────────────────────────────────────────────
162	     4)  APPOINTMENTS – POST
163	     ---------------------------------------------------------------- */
164	  export async function bookAppointment(data) {
165	    // Generate ICS file content for calendar integration
166	    const icsContent = generateIcsFile(data);
167	    
168	    if (isMockMode()) return legacyMockBook(data, icsContent);
169	  
170	    const headers = await authHeader();
171	    const payload = { ...data, shop_id: shopId() };
172	  
173	    const r = await fetch(`${API_BASE}/appointments/book`, {
174	      method: 'POST',
175	      headers,
176	      body: JSON.stringify(payload),
177	    });
178	    if (!r.ok) throw new Error(await r.text());
179	    
180	    // Get the response data
181	    const responseData = await r.json();
182	    
183	    // Add ICS content to the response
184	    return {
185	      ...responseData,
186	      icsContent,
187	      icsFilename: `appointment_${data.date.replace(/\//g, '')}_${data.start_time.replace(':', '')}.ics`
188	    };
189	  }
190	  
191	  /* ────────────────────────────────────────────────────────────────
192	     5)  CUSTOMERS API
193	     ---------------------------------------------------------------- */
194	  export async function fetchCustomers() {
195	    if (isMockMode()) {
196	      return []; // TODO: Add mock customer data when needed
197	    }
198	
199	    try {
200	      const headers = await authHeader();
201	      const r = await fetch(`${API_BASE}/customers?shop_id=${shopId()}`, { headers });
202	      
203	      if (!r.ok) throw new Error(await r.text());
204	      const data = await r.json();
205	      return data.customers || [];
206	    } catch (error) {
207	      console.error('Error fetching customers:', error);
208	      // Return empty array instead of throwing to avoid breaking UI
209	      return [];
210	    }
211	  }
212	  
213	  /* ────────────────────────────────────────────────────────────────
214	     6)  ChatGPT helper
215	     ---------------------------------------------------------------- */
216	  export async function callChatApi(messages) {
217	    if (isMockMode()) {
218	      return Promise.resolve({
219	        response: "This is a mock response. Please configure the OpenAI API to use the chat feature.",
220	        success: true
221	      });
222	    }
223	
224	    try {
225	      // Get config from localStorage
226	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
227	      const storageKey = `appConfig_${shop}`;
228	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
229	      
230	      // Check if OpenAI is enabled and API key exists
231	      if (!cfg.openai?.enabled || !cfg.openai?.apiKey) {
232	        throw new Error('OpenAI is not enabled or API key is missing');
233	      }
234	      
235	      const headers = await authHeader();
236	      
237	      // Use backend proxy instead of direct OpenAI call for security
238	      const response = await fetch(`${API_BASE}/chat`, {
239	        method: 'POST',
240	        headers,
241	        body: JSON.stringify({ 
242	          messages,
243	          shop_id: shopId()
244	        }),
