              // Format minutes for better readability
              const endHour = Math.floor(timeSlotEndMinutes / 60);
              const endMin = timeSlotEndMinutes % 60;
              const formattedEndTime = `${String(endHour).padStart(2, '0')}:${String(endMin).padStart(2, '0')}`;

              console.log(`Time conflict: ${formattedHour}:${formattedMinute} conflicts with appointment at ${apptHour}:${apptMinute} (duration: ${appointmentDuration}min). Our service would end at ${formattedEndTime}`);
            }

            return hasOverlap;
          });

          // Add available time slot
          if (isAvailable) {
            times.push(timeSlot);
          }

          // Move to next time slot
          currentMinute += interval;
          if (currentMinute >= 60) {
            currentHour += 1;
