              const endHour = Math.floor(timeSlotEndMinutes / 60);
              const endMin = timeSlotEndMinutes % 60;
              const formattedEndTime = `${String(endHour).padStart(2, '0')}:${String(endMin).padStart(2, '0')}`;

              console.log(`Time conflict: ${timeSlot} conflicts with appointment at ${appt.start_time} (duration: ${appointmentDuration}min). Our service would end at ${formattedEndTime}`);
            }

            return hasOverlap;
