              const formattedEndTime = `${String(endHour).padStart(2, '0')}:${String(endMin).padStart(2, '0')}`;

              console.log(`Time conflict: ${formattedHour}:${formattedMinute} conflicts with appointment at ${apptHour}:${apptMinute} (duration: ${appointmentDuration}min). Our service would end at ${formattedEndTime}`);
