        } else {
          console.log("No time slots available for", date.display);
          // Force default times if none are available - just for weekdays
          const dayOfWeek = new Date(date.value).getDay();

          if (dayOfWeek >= 1 && dayOfWeek <= 5) { // Monday to Friday
